namespace Themis.Kernel.Primitives;

/// <summary>Identifiers are UUID version 7, generated by the application, time-ordered, never reused (D-17).</summary>
public static class EntityId
{
    public static Guid New() => Guid.CreateVersion7();
}

/// <summary>A strongly typed identifier wrapping a UUID (D-17). One type per entity, so ids cannot be mixed up.</summary>
public interface IEntityId
{
    Guid Value { get; }
}

/// <summary>The user a command runs as (Phase 0 Specification, User).</summary>
public readonly record struct UserId(Guid Value) : IEntityId
{
    public static UserId New() => new(EntityId.New());

    public override string ToString() => Value.ToString();
}

/// <summary>One execution of a command; written on every ledger entry and audit event it produces (R-LED-03, R-AUD-01).</summary>
public readonly record struct CommandId(Guid Value) : IEntityId
{
    public static CommandId New() => new(EntityId.New());

    public override string ToString() => Value.ToString();
}
